    function isFilledEl(el) {
        var style = el.getAttribute('style') || '';
        if (/FILL[\'"]?\s*1/.test(style)) return true;
        if (el.getAttribute('data-weight') === 'fill') return true;
        return false;
    }

    function buildSvg(name, filled) {
        var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svg.setAttribute('width', '1em');
        svg.setAttribute('height', '1em');
        svg.setAttribute('aria-hidden', 'true');
        svg.setAttribute('focusable', 'false');
        svg.style.display = 'inline-block';
        svg.style.verticalAlign = 'middle';
        svg.style.flexShrink = '0';

        var real = ICONS_REAL[name];
        if (real) {
            svg.setAttribute('viewBox', '0 -960 960 960');
            svg.setAttribute('fill', 'currentColor');
            svg.innerHTML = '<path d="' + ((filled && real.dFill) || real.d) + '"/>';
            return svg;
        }

        if (window.console && name) console.warn('[SOUCOFFE] Icône inconnue : ' + name);
        return null;
    }

    // Même icône sous forme de chaîne HTML, pour les gabarits JS (innerHTML,
    // concaténations) : pas besoin d'appeler renderIcons() ensuite.
    function iconHtml(name, cls, filled) {
        var real = ICONS_REAL[name];
        if (!real) {
            if (window.console) console.warn('[SOUCOFFE] Icône inconnue : ' + name);
            return '';
        }
        return '<svg' + (cls ? ' class="' + cls + '"' : '') + ' data-icon="' + name + '" width="1em" height="1em" viewBox="0 -960 960 960" fill="currentColor" aria-hidden="true" focusable="false" style="display:inline-block;vertical-align:middle;flex-shrink:0">' +
            '<path d="' + ((filled && real.dFill) || real.d) + '"/></svg>';
    }

    function renderIcons() {
        var nodes = document.querySelectorAll('.material-symbols-outlined, [data-icon]:not(svg)');
        nodes.forEach(function (el) {
            var name = el.getAttribute('data-icon') || el.textContent.trim();
            var svg = buildSvg(name, isFilledEl(el));
            if (!svg) return;
            var classes = (el.getAttribute('class') || '')
                .replace(/material-symbols-outlined/g, '')
                .trim();
            if (classes) svg.setAttribute('class', classes);
            if (el.hasAttribute('data-icon')) svg.setAttribute('data-icon', el.getAttribute('data-icon'));
            el.replaceWith(svg);
        });
    }

    // Toute icône ajoutée APRÈS le chargement (bandeaux, boutons, cartes
    // générés par JS avec <span class="material-symbols-outlined">nom</span>)
    // est convertie automatiquement en SVG, sans que chaque appelant pense à
    // rappeler renderIcons(). Traitement en microtâche : fait avant le
    // prochain affichage, donc le nom de l'icône n'est jamais visible.
    var ICON_SELECTOR = '.material-symbols-outlined, [data-icon]:not(svg)';
